function loc(){const x=window.WonderI18n?.actualLocale?.()||document.documentElement.lang||"en";return L[x]?x:(alias[String(x).toLowerCase()]||"en")}
function t(k,v={}){return (L[loc()][k]||L.en[k]||k).replace(/\{(\w+)\}/g,(_,n)=>String(v[n]??""))}
const clean=n=>Math.max(0,Math.floor(Number(n)||0));
function empty(){return{version:2,worldSchema:1,worldLevel:1,ownedBlocks:0,castleMaterials:0,completions:{},badges:[],buildings:["hall"]}}
function normBuildings(v,legacy=false){const a=Array.isArray(v)?v:[];if(legacy){const old=["tower","garden","library","observatory","gate"].filter(x=>a.includes(x)).length;return["hall",...buildings.slice(0,old).map(x=>x.id)]}const s=new Set(a.map(x=>x==="library"?"bridge":x));return["hall",...buildings.map(x=>x.id).filter(x=>s.has(x))]}
// Keep the reward store's version 2 readable by game tabs using the previous runtime.
function read(){try{const s=JSON.parse(localStorage.getItem(STORE)||"null");if(!s||![1,2,3].includes(s.version))return empty();const legacyBuildings=normBuildings(s.buildings,s.version===1),castleMaterials=s.castleMaterials==null?Math.floor(clean(s.starSand)/LEGACY):clean(s.castleMaterials),completions=s.completions&&typeof s.completions==="object"&&!Array.isArray(s.completions)?{...s.completions}:{};let builder=null;try{builder=JSON.parse(localStorage.getItem(BUILD)||localStorage.getItem(PREVIOUSBUILD)||localStorage.getItem(LEGACYBUILD)||"null")}catch{}let owned=clean(s.ownedBlocks);if(s.worldSchema!==1&&s.version!==3){if(builder?.version===2&&builder.worldLevel){owned=clean(builder.ownedBlocks)+Math.max(0,Object.keys(completions).length-clean(builder.creditedCount))}else{const placed=Array.isArray(builder?.blocks)?builder.blocks.filter(b=>b&&b.source!=="starter").length:0;owned=Math.max(Object.keys(completions).length,castleMaterials+placed+buildings.filter(b=>legacyBuildings.includes(b.id)).reduce((n,b)=>n+b.cost,0))}}return{version:2,worldSchema:1,worldLevel:Math.max(1,Math.min(6,Math.max(clean(s.worldLevel),clean(builder?.worldLevel),legacyBuildings.length))),ownedBlocks:owned,castleMaterials,completions,badges:Array.isArray(s.badges)?[...new Set(s.badges.filter(x=>typeof x==="string"))]:[],buildings:legacyBuildings}}catch{return empty()}}

function storeWritable(){try{const old=JSON.parse(localStorage.getItem(STORE)||"null");return !old||[1,2,3].includes(old.version)}catch{return false}}
function save(s){if(!storeWritable())return false;try{localStorage.setItem(STORE,JSON.stringify(s));window.dispatchEvent(new Event("weightplay:castle-updated"));return true}catch{return false}}
// A starter house uses only four level-one materials and complete unit cubes.
function starterBlocks(){const blocks=[];const add=(x,y,z,type)=>blocks.push({id:`starter-${blocks.length}`,type,x,y,z,source:"starter"});for(let y=0;y<2;y++)for(let x=-2;x<=2;x++)for(let z=-3;z<=1;z++)if((Math.abs(x)===2||z===-3||z===1)&&!(x===0&&z===1)){add(x,y,z,y===1&&z===1&&Math.abs(x)===1?"glass":(Math.abs(x)===2&&Math.abs(z+1)===2?"wood":"stone"))}for(let layer=0;layer<3;layer++)for(let x=-2+layer;x<=2-layer;x++)for(let z=-3+layer;z<=1-layer;z++)add(x,2+layer,z,"roof");return blocks}
function normalizeStarter(b,s){if(b.presetRevision===2)return false;let changed=false;const pending=[];b.blocks=b.blocks.map(block=>{if(block.source!=="starter")return block;changed=true;const m=materials.find(m=>m.id===block.type),type=m?.level===1?block.type:(["gold","leaf","copper"].includes(block.type)?"wood":"stone"),unit={...block,type};delete unit.color;if(block.size?.some(v=>Math.abs(v-.94)>.001)){unit.x=Math.round(block.x);unit.y=Math.max(0,Math.round(block.y));unit.z=Math.round(block.z);delete unit.size;pending.push(unit);return null}delete unit.size;return unit}).filter(Boolean);for(const unit of pending){if(b.blocks.some(other=>overlaps(voxelBox(unit),voxelBox(other))))s.castleMaterials++;else b.blocks.push(unit)}b.presetRevision=2;return changed}
const LION_ACTIONS=["wiggle","roll","proud"],LION_ACTION_ICONS={wiggle:"↝",roll:"⤿",proud:"✦"};
function normalizeLion(value){if(!value||!Number.isInteger(value.x)||!Number.isInteger(value.z)||Math.abs(value.x)>BOARD||Math.abs(value.z)>BOARD)return null;return{x:value.x,y:Number.isFinite(value.y)&&value.y>=0&&value.y<=MAXY+1?Math.round(value.y*100)/100:0,z:value.z,rotation:clean(value.rotation)%4,action:LION_ACTIONS.includes(value.action)?value.action:"wiggle"}}
const LION_SCALE=.6;
function lionCollider(x,y,z){return{center:[x,y+.8,z],size:[1.16,1.65,1.16]}}
function lionSupport(b,x,y,z){if(y===0)return true;return b.blocks.some(q=>{const box=voxelBox(q);return Math.abs(box.center[0]-x)<.25&&Math.abs(box.center[2]-z)<.25&&box.size[0]>=.74&&box.size[2]>=.74&&Math.abs(box.center[1]+box.size[1]/2-y)<.015})}
function lionCellFree(b,x,y,z){return !b.blocks.some(q=>overlaps(voxelBox(q),lionCollider(x,y,z)))}
function lionTarget(hit){if(!hit||hit.normal?.[1]!==1||!["ground","block"].includes(hit.kind))return null;const x=hit.kind==="ground"?hit.x:hit.center[0],z=hit.kind==="ground"?hit.z:hit.center[2],y=hit.kind==="ground"?0:Math.round((hit.center[1]+hit.size[1]/2)*100)/100;return Number.isInteger(x)&&Number.isInteger(z)?{x,y,z}:null}
function setLion(change){const b=readBuild();if(b.available===false)return{saved:false,reason:"storage-unavailable"};if(change){const lion=normalizeLion(change);if(!lion||Math.abs(lion.x)>landRadius()||Math.abs(lion.z)>landRadius())return{saved:false,reason:"invalid"};if(!lionSupport(b,lion.x,lion.y,lion.z))return{saved:false,reason:"support"};if(!lionCellFree(b,lion.x,lion.y,lion.z))return{saved:false,reason:"occupied"};b.lion=lion}else b.lion=null;return commitConstruction(b,read())?{saved:true,lion:b.lion}:{saved:false,reason:"storage-unavailable"}}

function readBuild(){try{const x=JSON.parse(localStorage.getItem(BUILD)||localStorage.getItem(PREVIOUSBUILD)||localStorage.getItem(LEGACYBUILD)||"null"),arr=Array.isArray(x?.blocks)?x.blocks:[];if(x&&![1,2].includes(x.version))return{version:2,blocks:[],available:false};if(x?.version===2){const seen=new Set();return{version:2,presetRevision:clean(x.presetRevision),worldLevel:clean(x.worldLevel),ownedBlocks:clean(x.ownedBlocks),creditedCount:clean(x.creditedCount),lion:normalizeLion(x.lion),blocks:arr.filter(b=>b&&typeof b.id==="string"&&materials.some(m=>m.id===b.type)&&[b.x,b.y,b.z].every(Number.isFinite)&&Math.abs(b.x)<=BOARD+1&&Math.abs(b.z)<=BOARD+1&&b.y>=-1&&b.y<MAXY&&(!b.size||(Array.isArray(b.size)&&b.size.length===3&&b.size.every(v=>Number.isFinite(v)&&v>0&&v<=3)))&&!seen.has(b.id)&&seen.add(b.id)).slice(0,MAXBLOCKS)}}const seen=new Set(),legacy=arr.filter(b=>b&&["stone","roof","wood","glass"].includes(b.type)&&[b.x,b.y,b.z].every(Number.isInteger)&&Math.abs(b.x)<=6&&Math.abs(b.z)<=6&&b.y>=0&&b.y<8&&!seen.has(`${b.x},${b.y},${b.z}`)&&seen.add(`${b.x},${b.y},${b.z}`)).slice(0,256).map((b,i)=>({...b,id:`legacy-${i}`,source:"earned"}));return{version:2,presetRevision:2,lion:null,blocks:[...starterBlocks(),...legacy]}}catch{return{version:2,blocks:[],available:false}}}

function creditFirstClear(gameId,completionId="first-completion"){const g=String(gameId||"").trim(),c=String(completionId||"first-completion").trim();if(!/^[a-z0-9][a-z0-9-]{0,63}$/i.test(g)||!/^[a-z0-9][a-z0-9._-]{0,63}$/i.test(c))return{credited:false,reason:"invalid"};if(["stage-endless","stage-infinite","stage-survival","endless","infinite","survival"].includes(c.toLowerCase()))return{credited:false,reason:"non-stage-clear"};const s=read(),key=`${g}:${c}`;if(s.completions[key])return{credited:false,reason:"already-claimed",store:s};s.completions[key]=Date.now();if(!s.badges.includes(g))s.badges.push(g);s.castleMaterials+=REWARD;s.ownedBlocks+=REWARD;if(!save(s))return{credited:false,reason:"storage-unavailable"};window.WonderAnalytics?.track?.("castle_first_clear_reward",{game_id:g,completion_id:c,reward_amount:1,reward_type:"castle_block"});window.dispatchEvent(new CustomEvent("weightplay:castle-reward",{detail:{gameId:g,completionId:c,amount:1,currency:"castle-block"}}));return{credited:true,amount:1,currency:"castle-block",store:s}}
function upgradeWorld(expectedLevel){const s=read(),next=nextWorldLevel(s);if(!next)return{upgraded:false,reason:"max-level"};if(expectedLevel!=null&&Number(expectedLevel)!==next.level)return{upgraded:false,reason:"stale"};if(ownedBlocks(s)<next.required)return{upgraded:false,reason:"not-enough",required:next.required,store:s};const previous=worldLevel(s);s.worldLevel=next.level;s.buildings=["hall",...buildings.slice(0,next.level-1).map(b=>b.id)];return save(s)?{upgraded:true,previous,level:next.level,store:s}:{upgraded:false,reason:"storage-unavailable"}}
function build(){const z=upgradeWorld();return{...z,built:z.upgraded}}
function voxelBox(b){const size=b.size||[.94,.94,.94];return{center:[b.x,b.y+.47,b.z],size:clean(b.rotation)%2?[size[2],size[1],size[0]]:size}}
function overlaps(a,b){return a.center.every((v,i)=>Math.abs(v-b.center[i])<(a.size[i]+b.size[i])/2-.06)}
function touches(a,b){return a.center.some((v,axis)=>{const gap=Math.abs(v-b.center[axis])-(a.size[axis]+b.size[axis])/2;return gap>=-.08&&gap<=.2&&a.center.every((q,i)=>i===axis||Math.abs(q-b.center[i])<(a.size[i]+b.size[i])/2-.16)})}
function commitConstruction(b,s){if(!storeWritable()||b.available===false)return false;b.worldLevel=worldLevel(s);b.ownedBlocks=ownedBlocks(s);b.creditedCount=Object.keys(s.completions).length;let oldBuild,oldStore,ready=false;try{oldBuild=localStorage.getItem(BUILD);oldStore=localStorage.getItem(STORE);ready=true;localStorage.setItem(STORE,JSON.stringify(s));localStorage.setItem(BUILD,JSON.stringify(b))}catch{if(ready)for(const [key,value] of [[STORE,oldStore],[BUILD,oldBuild]])try{value==null?localStorage.removeItem(key):localStorage.setItem(key,value)}catch{}return false}window.dispatchEvent(new Event("weightplay:castle-updated"));return true}
function place(type,x,y,z,rotation=0){const s=read(),material=materials.find(m=>m.id===type);if(!material||![x,y,z].every(Number.isFinite)||Math.abs(x)>landRadius(s)||Math.abs(z)>landRadius(s)||y<0||y>=MAXY)return{placed:false,reason:"invalid"};if(worldLevel(s)<material.level)return{placed:false,reason:"locked",level:material.level};const b=readBuild(),box=voxelBox({x,y,z});if(b.available===false)return{placed:false,reason:"storage-unavailable"};if(b.blocks.length>=MAXBLOCKS)return{placed:false,reason:"full"};if(b.blocks.some(q=>overlaps(box,voxelBox(q)))||(b.lion&&overlaps(box,lionCollider(b.lion.x,b.lion.y,b.lion.z))))return{placed:false,reason:"occupied"};if(y>0&&!b.blocks.some(q=>touches(box,voxelBox(q))))return{placed:false,reason:"support"};if(s.castleMaterials<1)return{placed:false,reason:"not-enough"};const id=`block-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;b.blocks.push({id,type,x,y,z,rotation:clean(rotation)%4,source:"earned"});s.castleMaterials--;return commitConstruction(b,s)?{placed:true,id,store:s,builder:b}:{placed:false,reason:"storage-unavailable"}}
// Recover exactly one selected voxel. Neighbouring voxels stay in place.
function remove(x,y,z){const b=readBuild();if(b.available===false)return{removed:false,reason:"storage-unavailable"};const i=typeof x==="string"?b.blocks.findIndex(q=>q.id===x):b.blocks.findIndex(q=>q.x===x&&q.y===y&&q.z===z);if(i<0)return{removed:false,reason:"invalid"};const removed=b.blocks[i];if(b.lion&&b.lion.y>0){const box=voxelBox(removed);if(Math.abs(box.center[0]-b.lion.x)<.25&&Math.abs(box.center[2]-b.lion.z)<.25&&Math.abs(box.center[1]+box.size[1]/2-b.lion.y)<.015)return{removed:false,reason:"occupied"}}b.blocks.splice(i,1);const s=read();s.castleMaterials++;return commitConstruction(b,s)?{removed:true,store:s}:{removed:false,reason:"storage-unavailable"}}
function turnBlock(id){const b=readBuild();if(b.available===false)return{rotated:false,reason:"storage-unavailable"};const block=b.blocks.find(q=>q.id===id);if(!block)return{rotated:false,reason:"invalid"};const before=voxelBox(block);block.rotation=(clean(block.rotation)+1)%4;const after=voxelBox(block);if(before.size.some((v,i)=>v!==after.size[i])&&b.blocks.some(q=>q.id!==id&&overlaps(after,voxelBox(q))))return{rotated:false,reason:"occupied"};if(b.lion&&(!lionSupport(b,b.lion.x,b.lion.y,b.lion.z)||overlaps(after,lionCollider(b.lion.x,b.lion.y,b.lion.z))))return{rotated:false,reason:"occupied"};return commitConstruction(b,read())?{rotated:true,rotation:block.rotation,block}:{rotated:false,reason:"storage-unavailable"}}
function initializeWorld(){try{const builder=JSON.parse(localStorage.getItem(BUILD)||"null"),store=JSON.parse(localStorage.getItem(STORE)||"null");if(store&&![1,2,3].includes(store.version))return false;if(builder?.version===2&&builder.worldLevel&&builder.presetRevision===2&&store?.worldSchema===1)return true;const b=readBuild(),s=read();if(b.available===false)return false;normalizeStarter(b,s);return commitConstruction(b,s)}catch{return false}}
function dailyDiamonds(s=read()){return daily[worldLevel(s)-1]}
function dailyDiamondBonus(s=read()){return dailyDiamonds(s)-daily[0]}
function dailyRewardState(){const d=new Date(),today=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;try{const old=localStorage.getItem(DAILY),s=JSON.parse(old||"{}")||{};return{today,old,s,claimedToday:s.lastClaimDate===today,available:true,amount:dailyDiamonds()}}catch{return{today,claimedToday:false,available:false,amount:dailyDiamonds()}}}
function claimNow(){const r=dailyRewardState();if(r.claimedToday)return{claimed:false,reason:"already-claimed"};if(!r.available||!window.WeightPlayWallet?.addDiamonds)return{claimed:false,reason:"storage-unavailable"};try{localStorage.setItem(DAILY,JSON.stringify({...r.s,lastClaimDate:r.today,totalClaims:clean(r.s.totalClaims)+1}));window.WeightPlayWallet.addDiamonds(r.amount)}catch{try{r.old==null?localStorage.removeItem(DAILY):localStorage.setItem(DAILY,r.old)}catch{}return{claimed:false,reason:"storage-unavailable"}}window.WeightPlayAudio?.play?.("feedback.success");render();return{claimed:true,amount:r.amount}}
async function claimDailyReward(){try{return navigator.locks?.request?await navigator.locks.request("weightplay-daily-reward",claimNow):claimNow()}catch{return{claimed:false,reason:"storage-unavailable"}}}
const api=Object.freeze({key:STORE,builderKey:BUILD,builderVersion:9,rewardPerClear:1,read,readBuilder:readBuild,creditFirstClear,build,upgradeWorld,worldLevel,ownedBlocks,landSize,placeBlock:place,removeBlock:remove,rotateBlock:turnBlock,dailyDiamondBonus,dailyDiamonds,dailyRewardState,claimDailyReward,refresh:()=>render()});window.WeightPlayCastle=api;

const CUBE="/assets/weightplay-block-world-cube-v1.svg?v=20260930-publish-path-v2";
// The same small original pixel patterns power inventory icons and scene surfaces.
function tint(hex,amount){const c=color(hex);return c.map(v=>Math.max(0,Math.min(255,Math.round(v*255*amount))))}
function surfacePixels(m){const pixels=[];for(let y=0;y<8;y++)for(let x=0;x<8;x++){const hash=(x*17+y*31+x*y*7)%23;let hex=m.color,shade=.9+hash/115;switch(m.pattern){
case "brick":if(y%4===0||(x+(y<4?0:2))%4===0)shade=.64;break;
case "wood":shade=x%3===0?.7:1+(y%3)*.035;break;
case "roof":shade=y%3===0?.63:((x+Math.floor(y/3))%4===0?.83:1.1);break;
case "glass":if(x===0||y===0||x===7||y===7||x+y===6)hex=0xd9fcff;break;
case "leaf":shade=hash<7?.7:hash>17?1.32:1;break;
case "grain":shade=hash<5?.72:hash>17?1.25:1;break;
case "metal":shade=x===0||y===0||x===7||y===7?.68:x===1||y===1?1.3:1;if(x===5&&y===2)hex=0xfff4c3;break;
case "vein":if((x+y*2)%7===0)shade=.72;else if((x-y+8)%8===0)hex=m.id==="ice"?0xf1ffff:0xffffff;break;
case "rune":if((x===2&&y>1&&y<6)||(y===2&&x>1&&x<6)||(x===5&&y>2&&y<6))hex=0xa58bd7;break;
case "facet":hex=x+y<7?(x>y?0xdad4ff:0xafa0e1):(x>y?0x8069bf:0xc7b7f0);shade=1;break;
case "moss":hex=y<3&&hash>6?0x9aac5e:m.color;shade=hash<5?.7:1;break;
case "lava":if((x+y)%5===0||((x-y+8)%6===0))hex=hash%2?0xffb33f:0xf27028;else shade=.7;break;
case "aurora":hex=[0x69d9b4,0x58b9cc,0x9e86db,0x78caac][(y+Math.floor(x/3))%4];shade=1;break;
case "star":if((x===3&&y>1&&y<6)||(y===3&&x>1&&x<6))hex=0xffed9e;else if(hash===3)hex=0xa8d7f4;break;
case "void":{const d=Math.max(Math.abs(x-3.5),Math.abs(y-3.5));hex=d<1.5?0x201e39:d<2.5?0xb176c5:m.color;break}
case "pearl":hex=[0xf0dfdb,0xc7e6df,0xd3c7ea,0xf3ebd3][(Math.floor(x/2)+Math.floor(y/2))%4];shade=1;break;
case "galaxy":hex=hash<2?0xf4e7c1:Math.abs(y-x/2-2)<1.5?0x8870b0:m.color;break;
case "prism":hex=[0xe48893,0xf0c769,0x8bceb2,0x72bcd9,0xb499da][Math.floor((x+y)/3)%5];shade=1;break;
case "solar":hex=x===3||x===4||y===3||y===4?0xffed9c:hash<7?0xbf6735:m.color;break;
case "ancient":if((x===2&&y>1&&y<6)||(y===5&&x>1&&x<6)||(x===5&&y>1&&y<4))hex=0xdfca89;else if(hash<5)hex=0x3d5b55;break;
}pixels.push(tint(hex,shade))}return pixels}
const SURFACES=Object.fromEntries(materials.map(m=>[m.id,surfacePixels(m)]));
const MATERIAL_ATLAS=(()=>{const width=materials.length*8,data=new Uint8Array(width*8*4);materials.forEach((m,index)=>SURFACES[m.id].forEach((rgb,p)=>{const x=p%8,y=7-Math.floor(p/8),offset=(y*width+index*8+x)*4;data.set([...rgb,255],offset)}));return{width,data}})();
const MATERIAL_IMAGES=Object.fromEntries(materials.map(({id})=>{const c=document.createElement("canvas");c.width=c.height=96;const g=c.getContext("2d");if(!g)return[id,CUBE];const sides=[[[48,8],[88,30],[48,52],[8,30]],[[8,30],[48,52],[48,92],[8,70]],[[48,52],[88,30],[88,70],[48,92]]],at=(q,u,v)=>[q[0][0]+(q[1][0]-q[0][0])*u+(q[3][0]-q[0][0])*v,q[0][1]+(q[1][1]-q[0][1])*u+(q[3][1]-q[0][1])*v];sides.forEach((q,face)=>{for(let y=0;y<8;y++)for(let x=0;x<8;x++){g.fillStyle=`rgb(${SURFACES[id][y*8+x].map(v=>Math.min(255,Math.round(v*[1.12,.94,.73][face]))).join(",")})`;g.beginPath();[at(q,x/8,y/8),at(q,(x+1)/8,y/8),at(q,(x+1)/8,(y+1)/8),at(q,x/8,(y+1)/8)].forEach(([px,py],i)=>i?g.lineTo(px,py):g.moveTo(px,py));g.closePath();g.fill()}g.strokeStyle="#09242b99";g.lineWidth=1;g.beginPath();q.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.stroke()});return[id,c.toDataURL("image/png")]}));

