c.addEventListener("pointerdown",e=>{if(e.button!==0)return;c.setPointerCapture(e.pointerId);this.ptr.set(e.pointerId,{x:e.clientX,y:e.clientY,sx:e.clientX,sy:e.clientY,tap:true});if(this.ptr.size>1){for(const p of this.ptr.values())p.tap=false;const p=[...this.ptr.values()];this.lastPinch=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}});
